#!/usr/bin/env python3
"""Assemble scoped KDE native receipt from preserved evidence; no sampling."""
import json
from common import OUT,RUN,now,save,sha,source,load_lab,assert_resident,ui
lab=load_lab();frozen=source();resident=assert_resident(lab);state=ui(lab)
assert state['pid']==0 and state['state']=='stopped' and state['lastExit']['status']=='normal' and state['lastExit']['code']==0
read=lambda name:json.loads((OUT/name).read_text())
matrix=read('matrix.json');tray=read('tray-matrix.json');continuity=read('continuity-run1/receipt.json')
assert matrix['ok'] and len(matrix['attempts'])==12 and tray['ok'] and len(tray['attempts'])==4
assert continuity['verdict']=='pass'
ops=lab.cli(RUN,'operation.recent')['operations'];states=[{'id':o['id'],'state':o['state'],'copyStatus':o.get('copyStatus')} for o in ops]
assert len(states)==19 and all(o['state'] in ['completed','cancelled','failed'] and o['copyStatus']!='pending' for o in states)
fixtures=json.loads(lab.ssh(RUN,"python3 - <<'END'\nimport os,json,pathlib\na=[]\nfor p in pathlib.Path('/proc').iterdir():\n try:\n  if p.name.isdecimal() and p.stat().st_uid==os.getuid() and (p/'comm').read_text().strip() in ['putgd-ui','putgd-desktop-f']:a.append({'pid':int(p.name),'name':(p/'comm').read_text().strip()})\n except (FileNotFoundError,ProcessLookupError):pass\nprint(json.dumps(a))\nEND\n"));assert not fixtures
receipt={'schemaVersion':1,'timestampUtc':now(),'source':{k:frozen[k] for k in ['commit','tree','commitCount','archiveSha256'] if k in frozen},'version':read('install.json')['version'],'profile':'kde-wayland','evidenceClass':'graphical-kvm','vncPort':5934,'overlay':str(RUN),'resident':resident,'finalUi':state,'remainingFixtureOrHelperProcesses':fixtures,'functionalWaveComplete':True,'scope':'U11 current-source, single-head KDE local pipeline and helper lifecycle; not full desktop certification or physical performance budget','build':{'receipt':'build-receipt.json','devTests':40,'devFailures':0,'nodeFixture':'Node unavailable in guest; GNOME JS fixture is a host-suite gate','standardCMakeNinjaDistroQt':True,'sourceAndInstalledBinaryIdentityVerified':True},'achieved':{'nativeShortcutMatrix':{'passed':12,'receipt':'matrix.json'},'actualTrayActions':{'passed':4,'receipt':'tray-matrix.json'},'trayWithHelperAbsent':{'witness':'native-tray-menu-resume.png'},'fourViewsOpenThroughTrayAndNormalFinalClose':['settings-cycle1-lifecycle.json','history-cycle1-lifecycle.json','history-cycle2-lifecycle.json','activity-cycle1-lifecycle.json','about-cycle1-lifecycle.json'],'historySearchSelectionRestored':['native-history-search-applied.png','tray-history-cycle2.png'],'clipboardSurvivesHelperExit':'clipboard-survival.json','ownHelperAndNativeDialogCaptureRejected':['own-settings-window-rejected.json','own-native-dialog-rejected.json'],'nativeFolderDialog':'native-native-folder-picker-settled.png','draftCloseReopenConflictReloadCancel':['draft-close-lifecycle.json','native-restored-draft-field-visible.png','external-settings-change.json','native-conflict-restored-field.png','native-conflict-reload.png','settings-cancel-lifecycle.json','settings-restored.json'],'localOperationContinuesAfterHelperExit':{'receipt':'continuity-run1/receipt.json','operationId':continuity['operation']['id'],'normalExit':continuity['normalExit'],'largeArtifactBytes':536870912,'smallArtifactBytes':23},'runningKdeIntegration':'bridge-identity.json'},'operations':states,'pendingAcceptance':['Real S3 upload, public direct-link copy/paste and remote history deletion were not exercised in this local-only unit.','Continuity of a real ongoing S3 upload remains separate; the successful bounded continuity case uses finalized local files.','Multihead/fractional-scale/long-run leak and physical-machine performance budgets are not established by this single-head VM run.','Memory observation is prepared separately and remains unrun until root declares the cross-desktop functional wave quiet.'],'preservedIncidents':[{'receipt':'build-wrapper-interruption.json','description':'Initial host wrapper exited143 after package generation; ordinary incremental Release/CPack recovery recorded separately, no failed product tests hidden.'},{'receipt':'bridge-identity-command-error.log','description':'Read-only compositor /proc/exe hash denied; DBus owner/PID/start/version and installed executable hash recorded separately, no live compositor ELF hash claimed.'},{'receipt':'native-draft-root-entered.png','description':'First native folder Cancel click was covered by an expected rejection notification; follow-on draft input hit the still-open folder dialog. Escape visibly dismissed it; corrected actual draft actions have unique witnesses.'},{'receipt':'settings-restore-first-rejected.json','description':'Notification restoration without expectedRevision rejected with no mutation; subsequent guarded restoration succeeded.'}], 'replay':'README.md'}
evidence=[]
for path in sorted(OUT.rglob('*')):
 if path.is_file() and path.suffix in ['.json','.jsonl','.py','.png','.log','.xml','.md','.sh'] and '__pycache__' not in path.parts and path.name not in ['receipt.json','evidence-index.json']:
  evidence.append({'path':str(path.relative_to(OUT)),'sha256':sha(path)})
save(OUT/'evidence-index.json',{'timestampUtc':now(),'scope':'Explicit allowed local artifact extensions; no credentials, keys, guest profile or payload export','files':evidence})
receipt['evidenceIndexSha256']=sha(OUT/'evidence-index.json');save(OUT/'receipt.json',receipt)
print(json.dumps({'functionalWaveComplete':True,'receipt':str(OUT/'receipt.json'),'operations':len(states),'resident':resident,'helperPid':state['pid']}))
